  const createSession=(userId)=>{const token=newToken(),hash=tokenHash(token),exp=new Date(Date.now()+7*864e5).toISOString();db.prepare('INSERT INTO sessions VALUES(?,?,?,?)').run(hash,userId,exp,now());return token;};
  const createEmailToken=(userId,purpose,hours=2)=>{const token=newToken(),id=uid('tok'),t=now(),expires=new Date(Date.now()+hours*3600e3).toISOString();db.prepare('DELETE FROM email_tokens WHERE user_id=? AND purpose=? AND used_at IS NULL').run(userId,purpose);db.prepare('INSERT INTO email_tokens VALUES(?,?,?,?,?,?,?)').run(id,userId,purpose,tokenHash(token),expires,null,t);return token;};
  const deliverEmail=async(to,template,data)=>{const hook=process.env.EMAIL_DELIVERY_WEBHOOK;if(!hook)return {delivered:false,reason:'EMAIL_DELIVERY_WEBHOOK not configured'};try{const r=await fetch(hook,{method:'POST',headers:{'content-type':'application/json','authorization':process.env.EMAIL_DELIVERY_TOKEN?`Bearer ${process.env.EMAIL_DELIVERY_TOKEN}`:''},body:JSON.stringify({to,template,data})});return {delivered:r.ok,status:r.status};}catch(e){console.error('email delivery failed',e);return {delivered:false,reason:'delivery error'}}};
  const tokenFromReq=(req)=>{const bearer=String(req.headers.authorization||'').match(/^Bearer\s+(.+)$/i)?.[1];return parseCookies(req).verse_session||bearer||null;};
  const authUser=(req)=>{const token=tokenFromReq(req);if(!token)return null;const row=db.prepare(`${userSelect} JOIN sessions s ON s.user_id=u.id WHERE s.token_hash=? AND s.expires_at>?`).get(tokenHash(token),now());return cleanUser(row);};
  const requireAuth=(req,res,roles)=>{const u=authUser(req);if(!u)return bad(res,'Authentication required',401,'AUTH_REQUIRED'),null;if(u.status!=='active')return bad(res,'This account is not active.',403,'ACCOUNT_INACTIVE'),null;if(roles&&!roles.includes(u.role))return bad(res,'You do not have permission to perform this action.',403,'FORBIDDEN'),null;return u;};

  const subscriptionFor=(userId)=>{const row=db.prepare(`SELECT * FROM subscriptions WHERE user_id=? AND status IN ('trialing','active','pending','past_due') ORDER BY created_at DESC LIMIT 1`).get(userId);if(!row)return {id:null,user_id:userId,plan_code:'free',provider:'internal',status:'active',trial_ends_at:null,cancel_at_period_end:0};if(row.status==='trialing'&&row.trial_ends_at&&new Date(row.trial_ends_at)<new Date()){db.prepare("UPDATE subscriptions SET status='expired',updated_at=? WHERE id=?").run(now(),row.id);return {id:null,user_id:userId,plan_code:'free',provider:'internal',status:'active',trial_ends_at:null,cancel_at_period_end:0};}return row;};
  const entitlementFor=(userId)=>{const sub=subscriptionFor(userId),effectiveCode=['active','trialing'].includes(sub.status)?sub.plan_code:'free',plan=planFor(effectiveCode);return {subscription:sub,plan,purchasedPlan:planFor(sub.plan_code),features:{activePosts:plan.activePosts,seats:plan.seats,shortlist:plan.shortlist,bookings:plan.bookings}};};
