  const cleanJob=(r)=>r?({...r,featured:!!r.featured,paid:!!r.paid,portfolioRequired:!!r.portfolio_required,employerVerified:!!r.employerVerified,skills:parseJSON(r.skills_json),languages:parseJSON(r.languages_json),screeningQuestions:parseJSON(r.screening_questions_json),skills_json:undefined,languages_json:undefined,screening_questions_json:undefined,portfolio_required:undefined,employerVerified:!!r.employerVerified}):null;
  const jobsQuery=(where="j.status='published'",vals=[],order='j.featured DESC, j.created_at DESC',limit=100)=>db.prepare(`${jobBase} WHERE ${where} ORDER BY ${order} LIMIT ${Math.min(200,Math.max(1,limit))}`).all(...vals).map(cleanJob);
  const moderationFlags=(b)=>{const flags=[];const blob=`${b.title||''} ${b.description||''} ${b.requirements||''}`.toLowerCase();if(/whatsapp|telegram|dm me|pay.*fee|registration fee|security deposit/.test(blob))flags.push('Potential off-platform or fee language');if(!b.salary&&!b.compensationMin&&!b.compensationMax)flags.push('Compensation not disclosed');if((b.description||'').length<80)flags.push('Description is very short');if(!b.company)flags.push('Company missing');return flags;};
  const fitScore=(job,user)=>{let score=35;const skills=new Set((user.skills||[]).map(x=>x.toLowerCase()));const genres=new Set((user.genres||[]).map(x=>x.toLowerCase()));const js=(job.skills||[]).map(x=>x.toLowerCase());score+=Math.min(35,js.filter(x=>skills.has(x)).length*12);if(genres.has(String(job.genre||'').toLowerCase()))score+=15;if(user.location&&job.location&&String(job.location).toLowerCase().includes(String(user.location).split(',')[0].toLowerCase()))score+=10;if(job.workplace==='remote')score+=5;return Math.min(100,score);};

  const cleanPortfolio=(r)=>r?({...r,featured:!!r.featured,tags:parseJSON(r.tags_json),genres:parseJSON(r.genres_json),roles:parseJSON(r.roles_json),instruments:parseJSON(r.instruments_json),mediaMetadata:parseJSON(r.media_metadata_json,{}),tags_json:undefined,genres_json:undefined,roles_json:undefined,instruments_json:undefined,media_metadata_json:undefined}):null;
