  const jobSearchDoc=(j)=>({title:j.title,description:j.description,company:j.company,city:j.location,opportunityKind:j.opportunity_kind,functionArea:j.function_area,workplace:j.workplace,tags:[...(parseJSON(j.skills_json)),j.genre,j.type].filter(Boolean),genres:[j.genre].filter(Boolean),skills:parseJSON(j.skills_json),published:j.status==='published',url:`/opportunities/${j.id}`,updatedAt:j.updated_at});
  const talentSearchDoc=(u)=>({name:u.name,headline:u.headline,bio:u.bio,city:u.location,roleNames:u.roles||[],instrumentNames:u.instruments||[],tags:[...(u.skills||[]),...(u.gear||[]),...(u.software||[])],genres:u.genres||[],skills:u.skills||[],verified:!!u.verified,url:`/professionals/${u.id}`,updatedAt:u.updatedAt||u.createdAt});
  const actSearchDoc=(a)=>({name:a.name,headline:a.tagline,bio:a.bio,city:a.city,actType:a.act_type,tags:[...(parseJSON(a.genres_json)),...(parseJSON(a.event_types_json))],genres:parseJSON(a.genres_json),verified:!!a.verified,url:`/acts/${a.id}`,updatedAt:a.updated_at});
  const sampleSearchDoc=(r,owner)=>({title:r.title,description:r.description,name:owner?.name,headline:owner?.headline,city:owner?.location,tags:parseJSON(r.tags_json),genres:parseJSON(r.genres_json),roleNames:parseJSON(r.roles_json),instrumentNames:parseJSON(r.instruments_json),sampleType:r.type,creditedAs:r.credited_as,year:r.year,url:`/professionals/${r.user_id}`,updatedAt:r.created_at});
  const syncJob=(id)=>{const j=db.prepare('SELECT * FROM jobs WHERE id=?').get(id);if(j&&j.status==='published')indexSearchDocument('jobs',j.id,jobSearchDoc(j));else deleteSearchDocument('jobs',id);};
  const syncTalent=(id)=>{const u=cleanUser(db.prepare(`${userSelect} WHERE u.id=? AND u.status='active'`).get(id));if(u&&u.role==='jobseeker'&&u.profileComplete)indexSearchDocument('talent',u.id,talentSearchDoc(u));else deleteSearchDocument('talent',id);};
