  route('GET','/api/health',async(req,res)=>{try{db.prepare('SELECT 1 AS ok').get();json(res,200,{ok:true,service:'verse',time:now()});}catch{json(res,503,{ok:false,service:'verse',time:now()});}});
  route('GET','/api/readiness',async(req,res)=>{const production=process.env.NODE_ENV==='production';const checks={database:{ok:true,engine:'sqlite',note:production?'Durable only when DATABASE_PATH is mounted on persistent storage.':'SQLite is acceptable for local development.'},publicBaseUrl:{ok:!!process.env.PUBLIC_BASE_URL&&(!production||String(process.env.PUBLIC_BASE_URL).startsWith('https://'))},secureCookie:{ok:!production||process.env.SESSION_COOKIE_SECURE==='true'},allowedOrigins:{ok:!production||!!process.env.ALLOWED_ORIGINS},emailDelivery:{ok:!!process.env.EMAIL_DELIVERY_WEBHOOK},search:{ok:true,...searchStatus()},storage:{ok:!production||!!process.env.OBJECT_STORAGE_UPLOAD_WEBHOOK||process.env.ALLOW_LOCAL_UPLOADS==='true',provider:process.env.OBJECT_STORAGE_UPLOAD_WEBHOOK?'external':'local'},razorpay:{ok:!!(process.env.RAZORPAY_KEY_ID&&process.env.RAZORPAY_KEY_SECRET&&process.env.RAZORPAY_WEBHOOK_SECRET)},adminPassword:{ok:!production||process.env.ADMIN_PASSWORD!=='Admin@12345'&&String(process.env.ADMIN_PASSWORD||'').length>=14},demoData:{ok:!production||process.env.SEED_DEMO_DATA!=='true'}};const ok=Object.values(checks).every(x=>x.ok);json(res,ok?200:503,{ok,environment:process.env.NODE_ENV||'development',checks});});
  route('POST','/api/auth/register',async(req,res)=>{const lim=rateLimit(`auth:${req.socket.remoteAddress}`,20);if(!lim.ok)return bad(res,'Too many authentication attempts. Try again later.',429);const b=await parseJson(req);const name=cleanText(b.name,120),email=cleanText(b.email,254).toLowerCase(),password=String(b.password||''),role=b.role;if(name.length<2||!validEmail(email)||password.length<10||!['jobseeker','employer'].includes(role))return bad(res,'Use a valid name/email, a password of at least 10 characters, and a valid account type.');if(db.prepare('SELECT 1 FROM users WHERE email=?').get(email))return bad(res,'An account already exists for this email.',409);const id=uid('usr'),t=now(),{salt,hash}=hashPassword(password);db.prepare('INSERT INTO users(id,name,email,role,password_hash,password_salt,status,profile_complete,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?)').run(id,name,email,role,hash,salt,'active',0,t,t);db.prepare('INSERT INTO profiles(user_id,updated_at) VALUES(?,?)').run(id,t);const token=createSession(id);const user=cleanUser(db.prepare(`${userSelect} WHERE u.id=?`).get(id));log(user,'auth.register','user',id);json(res,201,{user},{'Set-Cookie':sessionCookie(token)});});
  route('POST','/api/auth/login',async(req,res)=>{const lim=rateLimit(`auth:${req.socket.remoteAddress}`,20);if(!lim.ok)return bad(res,'Too many authentication attempts. Try again later.',429);const b=await parseJson(req),email=cleanText(b.email,254).toLowerCase();const row=db.prepare('SELECT * FROM users WHERE email=?').get(email);if(!row||!verifyPassword(String(b.password||''),row.password_salt,row.password_hash))return bad(res,'Incorrect email or password.',401);if(row.status!=='active')return bad(res,'This account is not active.',403);db.prepare('UPDATE users SET last_login_at=?,updated_at=? WHERE id=?').run(now(),now(),row.id);const token=createSession(row.id);const user=cleanUser(db.prepare(`${userSelect} WHERE u.id=?`).get(row.id));log(user,'auth.login','user',row.id);json(res,200,{user},{'Set-Cookie':sessionCookie(token)});});
  route('POST','/api/auth/logout',async(req,res)=>{const token=tokenFromReq(req);if(token)db.prepare('DELETE FROM sessions WHERE token_hash=?').run(tokenHash(token));json(res,200,{ok:true},{'Set-Cookie':clearSessionCookie()});});
  route('GET','/api/me',async(req,res)=>{const u=requireAuth(req,res);if(u)json(res,200,{user:u});});

  route('POST','/api/auth/request-email-verification',async(req,res)=>{const u=requireAuth(req,res);if(!u)return;if(u.emailVerified)return json(res,200,{ok:true,alreadyVerified:true});const token=createEmailToken(u.id,'verify_email',24),base=(process.env.PUBLIC_BASE_URL||'http://localhost:5173').replace(/\/$/,'');const link=`${base}/verify-email?token=${encodeURIComponent(token)}`;const delivery=await deliverEmail(u.email,'verify_email',{name:u.name,link});json(res,200,{ok:true,delivery,...(process.env.NODE_ENV!=='production'?{debugLink:link}:{})});});
  route('POST','/api/auth/verify-email',async(req,res)=>{const b=await parseJson(req),hash=tokenHash(cleanText(b.token,500));const row=db.prepare("SELECT * FROM email_tokens WHERE token_hash=? AND purpose='verify_email' AND used_at IS NULL AND expires_at>?").get(hash,now());if(!row)return bad(res,'Verification link is invalid or expired.',400,'TOKEN_INVALID');const t=now();db.prepare('UPDATE email_tokens SET used_at=? WHERE id=?').run(t,row.id);db.prepare('UPDATE users SET email_verified=1,updated_at=? WHERE id=?').run(t,row.user_id);json(res,200,{ok:true});});
