  route('GET','/api/conversations',async(req,res)=>{const u=requireAuth(req,res,['jobseeker','employer']);if(!u)return;const rows=db.prepare(`SELECT c.id,c.job_id jobId,j.title jobTitle,c.candidate_id candidateId,c.employer_id employerId,uc.name candidateName,ue.name employerName,(SELECT body FROM messages m WHERE m.conversation_id=c.id ORDER BY m.created_at DESC LIMIT 1) lastMessage,(SELECT created_at FROM messages m WHERE m.conversation_id=c.id ORDER BY m.created_at DESC LIMIT 1) lastMessageAt,(SELECT COUNT(*) FROM messages m WHERE m.conversation_id=c.id AND m.sender_id<>? AND m.read_at IS NULL) unread FROM conversations c JOIN users uc ON uc.id=c.candidate_id JOIN users ue ON ue.id=c.employer_id LEFT JOIN jobs j ON j.id=c.job_id WHERE c.candidate_id=? OR c.employer_id=? ORDER BY COALESCE(lastMessageAt,c.created_at) DESC`).all(u.id,u.id,u.id);json(res,200,{conversations:rows});});
