  route('POST','/api/billing/cancel',async(req,res)=>{const u=requireAuth(req,res);if(!u)return;const sub=subscriptionFor(u.id);if(!sub.id)return bad(res,'No paid subscription found.',404);let atCycleEnd=['active'].includes(sub.status);if(sub.provider==='razorpay'&&sub.provider_subscription_id){try{await cancelGatewaySubscription(sub.provider_subscription_id,{atCycleEnd});}catch(e){if(atCycleEnd&&/no billing cycle|not cancellable/i.test(String(e.message||e))){atCycleEnd=false;await cancelGatewaySubscription(sub.provider_subscription_id,{atCycleEnd:false});}else throw e;}}const nextStatus=atCycleEnd?sub.status:'cancelled';db.prepare('UPDATE subscriptions SET cancel_at_period_end=?,status=?,updated_at=? WHERE id=?').run(atCycleEnd?1:0,nextStatus,now(),sub.id);log(u,atCycleEnd?'billing.cancel_scheduled':'billing.cancelled','subscription',sub.id);json(res,200,{ok:true,message:atCycleEnd?'Cancellation is scheduled for the end of the current billing period.':'Subscription cancelled.'});});
